"use strict";

let Shop1EnhanceRoot = null;
let Shop1EnhanceCardRow = null;
let Shop1EnhanceTitle = null;
let Shop1EnhanceLocalPlayerID = -1;

(function () {
    $.Schedule(0.0, Shop1Enhance_Init);
})();

function Shop1Enhance_Init() {
    Shop1EnhanceRoot = $.GetContextPanel();
    Shop1EnhanceCardRow = Shop1EnhanceRoot.FindChildTraverse("Shop1EnhanceCardRow");
    Shop1EnhanceTitle = Shop1EnhanceRoot.FindChildTraverse("Shop1EnhanceTitle");

    Shop1EnhanceLocalPlayerID = Players.GetLocalPlayer();

    GameEvents.Subscribe("shop1_enhance_show", Shop1Enhance_OnShow);
    GameEvents.Subscribe("shop1_enhance_close", Shop1Enhance_OnClose);
    Shop1Enhance_Hide();
}

function Shop1Enhance_Show() {
    if (!Shop1EnhanceRoot) return;
    Shop1EnhanceRoot.RemoveClass("Hidden");
}

function Shop1Enhance_Hide() {
    if (!Shop1EnhanceRoot) return;
    Shop1EnhanceRoot.AddClass("Hidden");
}

function Shop1Enhance_NormalizeChoices(rawChoices) {
    if (!rawChoices) return [];
    if (rawChoices instanceof Array) return rawChoices;

    let arr = [];
    let keys = Object.keys(rawChoices);
    keys = keys
        .filter(k => String(parseInt(k)) === k || /^\d+$/.test(k))
        .map(k => parseInt(k))
        .sort((a, b) => a - b);

    for (let i = 0; i < keys.length; i++) {
        let k = String(keys[i]);
        arr.push(rawChoices[k]);
    }
    return arr;
}

function Shop1Enhance_EnsureCards(count) {
    if (!Shop1EnhanceCardRow) return;

    while (Shop1EnhanceCardRow.GetChildCount() > count) {
        Shop1EnhanceCardRow.GetChild(Shop1EnhanceCardRow.GetChildCount() - 1).DeleteAsync(0);
    }

    while (Shop1EnhanceCardRow.GetChildCount() < count) {
        let btn = $.CreatePanel("Button", Shop1EnhanceCardRow, "");
        btn.AddClass("Shop1EnhanceCard");

        let icon = $.CreatePanel("Image", btn, "Shop1EnhanceCardIcon");
        icon.AddClass("Shop1EnhanceCardIcon");
        icon.SetAttributeString("scaling", "stretch-to-fit-preserve-aspect");

        let name = $.CreatePanel("Label", btn, "Shop1EnhanceCardName");
        name.AddClass("Shop1EnhanceCardName");

        let desc = $.CreatePanel("Label", btn, "Shop1EnhanceCardDesc");
        desc.AddClass("Shop1EnhanceCardDesc");
    }
}

function Shop1Enhance_GetLocalizedName(ability) {
    if (!ability) return "";
    let key = "#DOTA_Tooltip_Ability_" + ability;
    let text = $.Localize(key);
    if (text && text !== key) return text;
    key = "#" + ability;
    text = $.Localize(key);
    if (text && text !== key) return text;
    return ability;
}

function Shop1Enhance_GetLocalizedDesc(ability) {
    if (!ability) return "";
    let key = "#DOTA_Tooltip_Ability_" + ability + "_Description";
    let text = $.Localize(key);
    if (text && text !== key) return text;
    key = "#" + ability + "_Description";
    text = $.Localize(key);
    if (text && text !== key) return text;
    return "";
}

function Shop1Enhance_ResolveDialogVariables(vars) {
    if (!vars) return null;
    let resolved = {};
    for (let key of Object.keys(vars)) {
        let value = vars[key];
        if (value === null || value === undefined) continue;
        if (typeof value !== "string") {
            value = String(value);
        }
        if (value.length > 0 && value[0] === "#") {
            value = $.Localize(value);
        }
        resolved[key] = value;
    }
    return resolved;
}

function Shop1Enhance_ApplyDialogVariables(panel, vars) {
    if (!panel || !vars) return;
    for (let key of Object.keys(vars)) {
        panel.SetDialogVariable(key, vars[key]);
    }
}

function Shop1Enhance_ReplaceDialogTokens(text, vars) {
    if (!text || !vars) return text;
    let result = text;
    for (let key of Object.keys(vars)) {
        let value = vars[key];
        if (value === null || value === undefined) continue;
        let escaped = key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        let re = new RegExp("\\{(?:(?:s|d|f):)?" + escaped + "\\}", "g");
        result = result.replace(re, value);
    }
    return result;
}

function Shop1Enhance_FillCard(panel, data, index) {
    if (!panel) return;

    let ability = (data && data.ability) || "";
    let image = (data && data.image) || "";
    let displayName = (data && data.display_name) || "";
    let displayDesc = (data && data.display_desc) || "";
    let displayDescVars = (data && data.display_desc_vars) || null;

    let icon = panel.FindChildTraverse("Shop1EnhanceCardIcon");
    let nameLabel = panel.FindChildTraverse("Shop1EnhanceCardName");
    let descLabel = panel.FindChildTraverse("Shop1EnhanceCardDesc");

    if (!image && ability) {
        image = "s2r://panorama/images/spellicons/" + ability + "_png.vtex";
    }

    if (icon) {
        icon.SetImage(image || "");
        icon.ClearPanelEvent("onmouseover");
        icon.ClearPanelEvent("onmouseout");
        if (ability) {
            icon.SetPanelEvent("onmouseover", function () {
                $.DispatchEvent("DOTAShowAbilityTooltip", icon, ability);
            });
            icon.SetPanelEvent("onmouseout", function () {
                $.DispatchEvent("DOTAHideAbilityTooltip", icon);
            });
        }
    }

    if (nameLabel) {
        if (displayName) {
            nameLabel.text = displayName[0] === "#" ? $.Localize(displayName) : displayName;
        } else {
            nameLabel.text = Shop1Enhance_GetLocalizedName(ability);
        }
    }

    if (descLabel) {
        if (displayDesc) {
            if (displayDesc[0] === "#") {
                let resolvedVars = Shop1Enhance_ResolveDialogVariables(displayDescVars);
                if (resolvedVars) {
                    Shop1Enhance_ApplyDialogVariables(descLabel, resolvedVars);
                }
                let localized = $.Localize(displayDesc, descLabel);
                descLabel.text = Shop1Enhance_ReplaceDialogTokens(localized, resolvedVars);
            } else {
                descLabel.text = displayDesc;
            }
        } else {
            descLabel.text = Shop1Enhance_GetLocalizedDesc(ability);
        }
    }

    panel.RemoveClass("Disabled");
    panel.enabled = true;
    panel.hittest = true;

    if (!ability) {
        panel.AddClass("Disabled");
        panel.enabled = false;
        panel.hittest = false;
    } else {
        panel.SetPanelEvent("onactivate", function () {
            Shop1Enhance_OnPick(index);
        });
    }
}

function Shop1Enhance_OnShow(event) {
    if (!event) return;
    if (event.player_id !== Shop1EnhanceLocalPlayerID) return;

    if (Shop1EnhanceTitle) {
        if (event.title && event.title.length > 0) {
            Shop1EnhanceTitle.text = event.title[0] === "#" ? $.Localize(event.title) : event.title;
        } else {
            Shop1EnhanceTitle.text = $.Localize("#shop1_enhance_pick_title");
        }
    }

    Shop1Enhance_Show();

    let choices = Shop1Enhance_NormalizeChoices(event.choices);
    let count = choices.length;
    Shop1Enhance_EnsureCards(count);

    for (let i = 0; i < count; i++) {
        let data = choices[i] || {};
        let panel = Shop1EnhanceCardRow.GetChild(i);
        if (!panel) continue;
        Shop1Enhance_FillCard(panel, data, i + 1);
    }

}

function Shop1Enhance_OnClose(event) {
    if (!event) return;
    if (event.player_id !== Shop1EnhanceLocalPlayerID) return;
    Shop1Enhance_Hide();
}

function Shop1Enhance_OnPick(choiceIndex) {
    GameEvents.SendCustomGameEventToServer("shop1_enhance_choice", {
        PlayerID: Shop1EnhanceLocalPlayerID,
        choice_index: choiceIndex,
    });
}

